      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Extract Rabbit Test Fixtures",
      "activity_description": "Move the Rabbit @Rule test fixtures to a separate repository, publish as an artifact, and update dependencies in the main project (U2).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Consistent REST API Access",
      "activity_description": "Create an abstraction layer to allow consistent REST API access across Lattice, YARN, and Cloud Foundry platforms (U3).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement Library Artifact Registration",
      "activity_description": "Extend the artifact model to support 'library' types and update the DSL parser to handle include and exclude statements (U4).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement Named Channels",
      "activity_description": "Modify the stream parser and deployment properties to support named channels, allowing streaming pipelines without source or sink modules (U5).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A6",
      "activity_name": "Add StreamController Test Coverage",
      "activity_description": "Write and integrate API contract tests for the StreamController to verify contracts at build time (U6).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "Prevent Duplicate Stream Names",
      "activity_description": "Add validation logic to prevent users from creating streams with duplicate names, ensuring unique stream names (U7).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A8",
      "activity_name": "Integrate Kinesis Source Module",
      "activity_description": "Register and configure the Kinesis module as a source module to build streaming pipelines, including necessary testing (U8).",
      "most_likely_effort": 24
    }
  ],
